INSERT INTO persona (nombres, apellidos, fecha_nacimiento, cui, id_genero, id_orientacion_sexual, id_grupo_etnico, id_estado_civil, id_condicion_alfabetica, id_nivel_escolaridad, id_origen, es_extranjero) SELECT 'AGR_2023_403798', 'AGRAVIADOS', '2009-06-15', NULL, COALESCE((SELECT id_genero FROM genero WHERE UPPER(TRIM(nombre)) = UPPER('Mujer') ROWS 1),          (SELECT id_genero FROM genero WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1)), COALESCE((SELECT id_orientacion_sexual FROM orientacion_sexual WHERE UPPER(TRIM(nombre)) IN ('IGNORADO','SIN SELECCION','SD') ORDER BY id_orientacion_sexual ROWS 1),          (SELECT id_orientacion_sexual FROM orientacion_sexual ORDER BY id_orientacion_sexual ROWS 1)), COALESCE((SELECT id_grupo_etnico FROM grupo_etnico WHERE UPPER(TRIM(nombre)) IN ('IGNORADO','SD') ORDER BY id_grupo_etnico ROWS 1),          (SELECT id_grupo_etnico FROM grupo_etnico ORDER BY id_grupo_etnico ROWS 1)), COALESCE((SELECT id_estado_civil FROM estado_civil WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1),          (SELECT id_estado_civil FROM estado_civil WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1)), (SELECT id_condicion_alfabetica FROM condicion_alfabetica WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1), (SELECT id_nivel_escolaridad FROM nivel_escolaridad WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1), (SELECT u.id_ubicacion FROM ubicacion u  JOIN municipio m ON m.id_municipio = u.id_municipio  JOIN departamento d ON d.id_departamento = m.id_departamento  WHERE UPPER(TRIM(d.nombre)) = UPPER('Guatemala')    AND UPPER(TRIM(m.nombre)) = UPPER('Guatemala')    AND COALESCE(u.zona, '') = '6'  ORDER BY u.id_ubicacion DESC ROWS 1), 0 FROM RDB$DATABASE WHERE NOT EXISTS (SELECT 1 FROM persona p WHERE p.nombres = 'AGR_2023_403798' AND p.apellidos = 'AGRAVIADOS');
